  // paid, and how much programs have brought in.
  function ProgramRequestsPanel({ requests, paidPayments = [], profiles, onResolved, onDeletePayment, onIncrementTotalDue = null }) {
    const [tab, setTab] = useState("pending");
    const [programs, setPrograms] = useState([]);
    useEffect(() => {
      if (!sb) return;
      sb.from("training_programs").select("id, name, style").then(({ data, error: err }) => {
        if (!err && data) setPrograms(data);
      });
    }, []);

    const paidTotal = useMemo(() => paidPayments.reduce((sum, p) => sum + (Number(p.amount) || 0), 0), [paidPayments]);
    // Sept 14 2026, Jimmy: "same here" — same search box added to the Diet
    // plan requests Paid list, mirrored here.
    const [paidSearch, setPaidSearch] = useState("");
    const visiblePaidPayments = useMemo(() => {
      const q = paidSearch.trim().toLowerCase();
      if (!q) return paidPayments;
      return paidPayments.filter((p) => (p.client_name || "").toLowerCase().includes(q));
    }, [paidPayments, paidSearch]);

    return e("div", null,
      e(Segmented, {
        options: PROGRAM_REQUEST_TABS.map((t) => ({
          ...t,
          label: t.value === "pending" ? (requests.length > 0 ? `${t.label} (${requests.length})` : t.label) : (paidPayments.length > 0 ? `${t.label} (${paidPayments.length})` : t.label)
        })),
        value: tab, onChange: setTab
      }),
      tab === "pending"
        ? (requests.length === 0
            ? e("div", { style: { ...styles.empty, marginTop: 14 } }, e(ProgramsEmptyArt, {}), e("p", { style: styles.emptyText }, "No pending program requests."))
            : e("div", { style: { display: "flex", flexDirection: "column", gap: 10, marginTop: 14 } },
                requests.map((req) => {
                  const prog = req.program_id ? programs.find((p) => p.id === req.program_id) : null;
                  const clientProfile = profiles.find((p) => p.id === req.client_id) || null;
                  return e(ProgramRequestRow, { key: req.id, req, programName: prog ? `${styleLabel(prog.style)} — ${prog.name}` : null, clientProfile, onIncrementTotalDue, onResolved });
                })
              )
          )
        : (paidPayments.length === 0
            ? e("div", { style: { ...styles.empty, marginTop: 14 } }, e(ProgramsEmptyArt, {}), e("p", { style: styles.emptyText }, "No program payments logged yet."))
            : e("div", { style: { marginTop: 14 } },
                e("div", { style: styles.dashGrid },
                  e("div", { style: styles.dashTile }, e("span", { style: styles.profileLabel }, "Collected"), e("span", { style: styles.dashTileValue }, `$${paidTotal.toLocaleString()}`)),
                  e("div", { style: styles.dashTile }, e("span", { style: styles.profileLabel }, "Clients"), e("span", { style: styles.dashTileValue }, String(paidPayments.length)))
                ),
                e("div", { style: { display: "flex", alignItems: "center", justifyContent: "space-between", marginTop: 14, marginBottom: 4 } },
                  e("div", { style: styles.rosterSearchWrap },
                    e(Icon, { name: "search", size: 14, color: C.ink3 }),
                    e("input", {
                      style: styles.rosterSearchInput, type: "text", value: paidSearch,
                      onChange: (ev) => setPaidSearch(ev.target.value),
                      placeholder: "Search by name…"
                    }),
                    paidSearch && e("button", {
                      type: "button", onClick: () => setPaidSearch(""), style: styles.rosterSearchClear, "aria-label": "Clear search"
                    }, e(Icon, { name: "x", size: 12, color: C.ink3 }))
                  ),
                  e("span", { style: styles.rosterCount }, visiblePaidPayments.length, "/", paidPayments.length)
                ),
                visiblePaidPayments.length === 0
                  ? e("div", { style: styles.empty }, e("p", { style: styles.emptyText }, `No payments match "${paidSearch.trim()}".`))
                  : e("div", { style: { display: "flex", flexDirection: "column", gap: 10, marginTop: 10 } },
                      visiblePaidPayments.map((p) => {
                        const prog = p.program_id ? programs.find((pr) => pr.id === p.program_id) : null;
                        return e("div", { key: p.id, style: styles.trainerStatCard },
                          e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "flex-start", gap: 8 } },
                            e("div", { style: { display: "flex", flexDirection: "column", gap: 3 } },
                              e("span", { style: styles.exerciseName }, p.client_name || "Unknown client"),
                              e("span", { style: styles.muscleSubText }, prog ? `${styleLabel(prog.style)} — ${prog.name}` : (p.note || "Program"))
                            ),
                            e("div", { style: { display: "flex", alignItems: "center", gap: 10 } },
                              e("div", { style: { display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 3 } },
                                e("span", { style: styles.rosterVol }, `$${Number(p.amount).toLocaleString()}`),
                                e("span", { style: styles.muscleSubText }, fmtDate((p.paid_on || "").slice(0, 10)))
                              ),
                              onDeletePayment && e("button", {
                                style: styles.deleteBtn, onClick: () => onDeletePayment(p), "aria-label": "Delete payment", title: "Delete payment"
                              }, e(Icon, { name: "trash", size: 15 }))
                            )
                          )
                        );
                      })
                    )
              )
          )
    );
  }

  function ExerciseForm({ values, onChange, onSave, onCancel, saving, showDayField, showWeekField, showWeightField, saveLabel = "Save", isEditing = false, savedFlash = false }) {
    return e("div", { style: { ...styles.sessionForm, marginTop: 10, marginBottom: 0 } },
      // Same one-mic "speak the whole exercise" experience as the Log
      // feature's New Exercise form. This form used to also have small
      // per-field mics on the Exercise picker, Day label, and Notes — so
      // speaking a full exercise into whichever one was handy just dumped
      // the raw sentence as plain text into that one field, instead of
      // splitting it out (Jimmy, Sept 9 2026: "one speaker... not many one
      // like the one in log"). Those per-field mics are now switched off
      // (see showMic: false below, and the Day label/Notes fields further
      // down) so this is the ONLY mic in the form, exactly matching the Log
      // feature's mic surface. This uses the same voice-log-entry parsing,
      // then reshapes its per-set array into this form's compact string
      // fields via summarizeVoiceSets above.
      e(SmartVoiceEntryButton, {
        label: "Speak this exercise — name, sets, weight",
        onParsed: (result) => {
          const next = { ...values };
          if (showDayField && result.workoutTitle && !values.dayLabel) next.dayLabel = result.workoutTitle;
          if (result.exerciseName) next.exercise = result.exerciseName;
          if (Array.isArray(result.sets) && result.sets.length) {
            const summary = summarizeVoiceSets(result.sets);
            if (summary.setsReps) next.setsReps = summary.setsReps;
            if (summary.rest) next.rest = summary.rest;
            if (showWeightField && summary.weight) next.weight = summary.weight;
          }
          onChange(next);
        }
      }),
      // Only ClientCustomProgramCard's trainer-written, client-specific
      // programs pass showWeekField — the shared TRAINING_STYLES library
      // above has no week concept, so every existing call site here leaves
      // it undefined and sees no change.
      showWeekField && e("div", { style: { display: "flex", gap: 8 } },
        e("input", {
          style: { ...styles.input, flex: 1 }, placeholder: "Week label (e.g. Week 1)",
          value: values.weekLabel, onChange: (ev) => onChange({ ...values, weekLabel: ev.target.value })
        })
      ),
      showDayField && e("div", { style: { display: "flex", gap: 8, marginTop: showWeekField ? 10 : 0 } },
        e("input", {
          style: { ...styles.input, flex: 1 }, placeholder: "Day label (e.g. Day 1 — Squat)",
          value: values.dayLabel, onChange: (ev) => onChange({ ...values, dayLabel: ev.target.value })
        })
      ),
      e("div", { style: (showDayField || showWeekField) ? { marginTop: 10 } : {} },
        // Sept 9 2026: this field's own mic is switched off here, same as the
        // Log form already does — the SmartVoiceEntryButton above is now the
        // one and only mic in this form (matching Jimmy's "one speaker, not
        // many like the log" ask), so a second mic that only fills the raw
        // spoken sentence into this one field would just be confusing again.
        e(ExercisePicker, {
          value: values.exercise, placeholder: "Search exercises… e.g. Bench Press",
          onSelect: (name) => onChange({ ...values, exercise: name }),
          showMic: false
        })
      ),
      e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
        e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Sets x reps (e.g. 3x8)", value: values.setsReps, onChange: (ev) => onChange({ ...values, setsReps: ev.target.value }) }),
        e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Rest (sec)", type: "number", min: "0", value: values.rest, onChange: (ev) => onChange({ ...values, rest: ev.target.value }) })
      ),
      showWeightField && e("div", { style: { marginTop: 10 } },
        e("input", { style: styles.input, placeholder: "Weight, kg — per set, e.g. 70x70x90 (optional)", type: "text", inputMode: "decimal", value: values.weight || "", onChange: (ev) => onChange({ ...values, weight: ev.target.value }) })
      ),
      e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
        e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Notes (optional)", value: values.notes, onChange: (ev) => onChange({ ...values, notes: ev.target.value }) })
      ),
      // Sept 14 2026, Jimmy: "can we do the same when the trainer wants to
      // assign a program for a client... when i add an exercise i want the
      // same tab to save and add another" — same "Save & add another"
      // pattern as the workout-log's New exercise sheet. Only makes sense
      // while adding a brand-new exercise (to an existing day, or as the
      // first exercise of a new day), not while editing one that already
      // exists.
      !isEditing && e("button", {
        type: "button",
        style: { ...styles.exSheetSaveAddAnotherBtn, ...(saving ? styles.btnDisabled : {}) },
        onClick: () => onSave(true), disabled: saving
      }, e(Icon, { name: "plus", size: 15, strokeWidth: 3 }), saving ? "Saving…" : "Save & add another"),
      savedFlash && e("div", { style: { display: "flex", alignItems: "center", gap: 6, color: C.good, fontSize: 12.5, fontWeight: 600, marginTop: 10 } },
        e(Icon, { name: "check", size: 14, color: C.good }), "Added — add the next exercise below."
      ),
      e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
        e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving, onClick: () => onSave(false) }, saving ? "Saving…" : isEditing ? saveLabel : "Finish & close"),
        e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: onCancel }, "Cancel")
      )
    );
  }

  // Sept 11 2026, Jimmy: "add the option to add bodyweight or seconds like
  // we did in log", "one option to add one weight theres no like for each
  // set", "no back arrow", and editing an exercise "goes to a alone
  // exercise with the same title but seperate" — this replaces the old
  // compact "3x8" + single weight-string fields, used only by
  // ClientCustomProgramCard below, with the exact same per-set grid the Log
  // tab already has: one row per set (its own reps-or-seconds, its own
  // weight, its own rest), plus the same Timed/Bodyweight toggle. Editing an
  // exercise never shows Week/Day fields at all (those don't change on a
  // per-exercise edit — only the "add" version of this form ever needs
  // them), and `contextLabel`, when set, renders a small "editing under
  // Week X · Day Y" breadcrumb plus a proper back-style Cancel control
  // instead of a bare text link — so editing reads as "still inside this
  // day," not as a new, disconnected entry with nothing to click to leave.
  function ProgramSetsForm({ values, onChange, onSave, onCancel, saving, showWeekField, showDayField, saveLabel = "Save", contextLabel, savedFlash = false }) {
    function updateSet(i, field, v) {
      onChange({ ...values, sets: values.sets.map((s, idx) => (idx === i ? { ...s, [field]: v } : s)) });
    }
    // Sept 12 2026, Jimmy: "easier to add them" — same pre-fill-from-last-set
    // behavior as the workout-log sheets above.
    function addSet() {
      const last = values.sets.length > 0 ? values.sets[values.sets.length - 1] : null;
      onChange({ ...values, sets: [...values.sets, last ? { ...last } : { reps: "", weight: "", rest: "" }] });
    }
    function removeSet(i) {
      if (values.sets.length === 1) return;
      onChange({ ...values, sets: values.sets.filter((_, idx) => idx !== i) });
    }
    const isTimed = values.isTimed;
    const isBodyweight = values.isBodyweight;
    return e("div", { style: { ...styles.sessionForm, marginTop: 10, marginBottom: 0, ...(contextLabel ? { borderLeft: `2px solid ${C.brand}` } : {}) } },
      contextLabel && e("div", { style: { display: "flex", alignItems: "center", gap: 6, marginBottom: 10 } },
        e("span", { style: { fontFamily: "'JetBrains Mono', monospace", fontSize: 10.5, fontWeight: 700, color: C.ink3, letterSpacing: "0.05em", textTransform: "uppercase" } }, contextLabel)
      ),
      e(SmartVoiceEntryButton, {
        label: "Speak this exercise — name, sets, weight",
        onParsed: (result) => {
          const next = { ...values };
          if (result.exerciseName) next.exercise = result.exerciseName;
          if (Array.isArray(result.sets) && result.sets.length) {
            next.sets = result.sets.map((s) => ({ reps: s.reps != null ? String(s.reps) : "", weight: s.weight != null ? String(s.weight) : "", rest: s.rest != null ? String(s.rest) : "" }));
          }
          onChange(next);
        }
      }),
      showWeekField && e("div", { style: { display: "flex", gap: 8 } },
        e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Week label (e.g. Week 1)", value: values.weekLabel, onChange: (ev) => onChange({ ...values, weekLabel: ev.target.value }) })
      ),
      showDayField && e("div", { style: { display: "flex", gap: 8, marginTop: showWeekField ? 10 : 0 } },
        e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Day label (e.g. Day 1 — Squat)", value: values.dayLabel, onChange: (ev) => onChange({ ...values, dayLabel: ev.target.value }) })
      ),
      e("div", { style: (showDayField || showWeekField) ? { marginTop: 10 } : {} },
        e(ExercisePicker, { value: values.exercise, placeholder: "Search exercises… e.g. Bench Press", onSelect: (name) => onChange({ ...values, exercise: name }), showMic: false })
      ),
      e("div", { style: { display: "flex", alignItems: "center", justifyContent: "space-between", flexWrap: "wrap", gap: 8, marginTop: 12 } },
        e("label", { style: { ...styles.formLabel, marginBottom: 0 } }, "Sets"),
        e("div", { style: { display: "flex", gap: 6 } },
          e("button", {
            type: "button",
            style: { ...styles.demoToggleBtn, marginTop: 0, ...(isTimed ? { background: C.brandSoft, color: C.brand, borderColor: C.brand } : {}) },
            onClick: () => onChange({ ...values, isTimed: !isTimed })
          }, e(Icon, { name: "clock", size: 12 }), " Timed"),
          e("button", {
            type: "button",
            style: { ...styles.demoToggleBtn, marginTop: 0, ...(isBodyweight ? { background: C.brandSoft, color: C.brand, borderColor: C.brand } : {}) },
            onClick: () => onChange({ ...values, isBodyweight: !isBodyweight })
          }, "Bodyweight")
        )
      ),
      e("div", { style: styles.setRows },
        e("div", { style: { ...styles.setRowHeader, ...(isBodyweight ? { gridTemplateColumns: "26px 1fr 1fr 24px" } : {}) } },
          e("span", { style: styles.setColLabel }, "SET"),
          e("span", { style: styles.setColLabel }, isTimed ? "SECONDS" : "REPS"),
          !isBodyweight && e("span", { style: styles.setColLabel }, "WEIGHT"),
          e("span", { style: styles.setColLabel }, "REST (S)"),
          e("span", null)
        ),
        values.sets.map((s, i) => e("div", { key: i, style: { ...styles.setRow, ...(isBodyweight ? { gridTemplateColumns: "26px 1fr 1fr 24px" } : {}) } },
          e("span", { style: styles.setIndex }, i + 1),
          e("input", { type: "number", min: "0", value: s.reps, onChange: (ev) => updateSet(i, "reps", ev.target.value), style: styles.setInput, placeholder: isTimed ? "30" : "8" }),
          !isBodyweight && e("input", { type: "number", min: "0", step: "0.5", value: s.weight, onChange: (ev) => updateSet(i, "weight", ev.target.value), style: styles.setInput, placeholder: "60" }),
          e("input", { type: "number", min: "0", value: s.rest, onChange: (ev) => updateSet(i, "rest", ev.target.value), style: styles.setInput, placeholder: "90" }),
          e("button", { style: styles.rowDelete, onClick: () => removeSet(i), disabled: values.sets.length === 1, "aria-label": "Remove set" }, e(Icon, { name: "x", size: 14 }))
        ))
      ),
      e("button", { type: "button", style: styles.addSetBtn, onClick: addSet }, e(Icon, { name: "plus", size: 13, strokeWidth: 3 }), "Add set"),
      e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
        e("input", { style: { ...styles.input, flex: 1 }, placeholder: "Notes (optional)", value: values.notes, onChange: (ev) => onChange({ ...values, notes: ev.target.value }) })
      ),
      // Sept 14 2026, Jimmy: "can we do the same when the trainer wants to
      // assign a program for a client... when i add an exercise i want the
      // same tab to save and add another" — same "Save & add another"
      // pattern as the workout-log's New exercise sheet. contextLabel is
      // only ever passed while editing an existing exercise (see the
      // "Editing under ..." call site below), so it doubles as the signal
      // for "this is a brand-new exercise, adding another makes sense."
      !contextLabel && e("button", {
        type: "button",
        style: { ...styles.exSheetSaveAddAnotherBtn, ...(saving ? styles.btnDisabled : {}) },
        onClick: () => onSave(true), disabled: saving
      }, e(Icon, { name: "plus", size: 15, strokeWidth: 3 }), saving ? "Saving…" : "Save & add another"),
      savedFlash && e("div", { style: { display: "flex", alignItems: "center", gap: 6, color: C.good, fontSize: 12.5, fontWeight: 600, marginTop: 10 } },
        e(Icon, { name: "check", size: 14, color: C.good }), "Added — add the next exercise below."
      ),
      e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
        e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving, onClick: () => onSave(false) }, saving ? "Saving…" : contextLabel ? saveLabel : "Finish & close"),
        e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px", display: "flex", alignItems: "center", gap: 4 }, onClick: onCancel }, e(Icon, { name: "back", size: 13 }), "Cancel")
      )
    );
  }

  // Manual "mark as paid" gate for a self-train client's access to whichever ONE
  // program they've picked from the shared library — same pattern as the diet
  // plan unlock (trainer/manager enters what was received and when, no real
  // payment gateway involved yet). Priced and unlocked per program, not as a
  // whole-library subscription: it reads the client's current pick from
  // client_program_assignments and pays for that specific row. Picking a
  // different program later resets it back to unpaid (a fresh assignment row
  // is always paid = false until marked otherwise). Only ever shown to a
  // trainer/manager viewing a self-train client's own detail page; a client
  // can never see or trigger this themselves.
  function ProgramPaymentCard({ clientProfile, onUpdate, refreshKey = 0, onIncrementTotalDue = null }) {
    const clientId = clientProfile ? clientProfile.id : null;
    const [loaded, setLoaded] = useState(false);
    const [assignment, setAssignment] = useState(null);
    const [program, setProgram] = useState(null);
    const [unlocking, setUnlocking] = useState(false);
    const [amount, setAmount] = useState(String(PROGRAM_PRICE));
    const [date, setDate] = useState(todayISO());
    const [saving, setSaving] = useState(false);
    const [error, setError] = useState("");
    // Sept 13 2026, Jimmy: inline "are you sure" instead of window.confirm().
    const [confirmRevoke, setConfirmRevoke] = useState(false);

    // refreshKey is bumped by the sibling ClientProgramCard whenever the
    // client's pick changes — this card fetches its own copy of the
    // assignment independently, so without this it'd keep showing stale
    // "hasn't picked a program yet" after a pick was just made.
    useEffect(() => { load(); }, [clientId, refreshKey]);

    async function load() {
      if (!sb || !clientId) { setLoaded(true); return; }
      setLoaded(false);
      const { data: rows } = await sb.from("client_program_assignments").select("*").eq("client_id", clientId).order("assigned_at", { ascending: false }).limit(1);
      const a = rows && rows[0];
      setAssignment(a || null);
      if (a) {
        const { data: prog } = await sb.from("training_programs").select("*").eq("id", a.program_id).maybeSingle();
        setProgram(prog || null);
      } else {
        setProgram(null);
      }
      setLoaded(true);
    }

    async function handleSubscribe() {
      setError("");
      const amt = Number(amount);
      if (!amount || isNaN(amt) || amt <= 0) { setError("Enter a valid amount."); return; }
      if (!date) { setError("Pick a date."); return; }
      if (!sb || !clientProfile || !assignment) { setError("Backend not configured yet."); return; }
      setSaving(true);
      const { data: updated, error: err } = await sb.from("client_program_assignments").update({ paid: true, paid_at: date }).eq("id", assignment.id).select();
      if (err) { setSaving(false); setError("Couldn't save: " + err.message); return; }
      if (!updated || updated.length === 0) { setSaving(false); setError("Save was blocked by a permissions rule (0 rows updated) — this needs a database fix, not a retry. Tell your developer: RLS blocked update on client_program_assignments."); return; }
      // Log it as a real payment, same ledger as everything else this client pays.
      const label = program ? `${styleLabel(program.style)} — ${program.name}` : "Program";
      await sb.from("client_payments").insert([{ user_id: clientProfile.user_id, client_name: clientProfile.client_name, amount: amt, paid_on: date, note: `Program: ${label}`, program_id: assignment.program_id || null }]);
      // Sept 19 2026 inspection fix: same bug class the diet-plan unlock fix
      // closed a round ago — logged the payment but never bumped total_due,
      // so unlocking a program here made the client's shown balance go DOWN
      // by the unlock amount instead of adding it as a separate charge.
      if (onIncrementTotalDue) onIncrementTotalDue(clientId, amt);
      notifyClient(clientProfile.user_id, `Your program "${label}" is ready — check your Programs tab.`);
      setSaving(false);
      setUnlocking(false);
      setAmount("");
      setDate(todayISO());
      await load();
      if (onUpdate) onUpdate();
    }

    async function handleRevoke() {
      if (!sb || !assignment) return;
      setConfirmRevoke(false);
      const { data: updated, error: err } = await sb.from("client_program_assignments").update({ paid: false }).eq("id", assignment.id).select();
      if (err) { setError("Couldn't save: " + err.message); return; }
      if (!updated || updated.length === 0) { setError("Save was blocked by a permissions rule (0 rows updated)."); return; }
      await load();
      if (onUpdate) onUpdate();
    }

    if (!loaded) return null;

    if (!assignment) {
      return e("div", { style: { ...styles.sessionForm, marginTop: 20 } },
        e("span", { style: styles.profileLabel }, "Program payment"),
        e("p", { style: { ...styles.emptyText, marginTop: 6 } }, "This client hasn't picked a program from the library yet — nothing to charge for until they do.")
      );
    }

    const paid = !!assignment.paid;
    const label = program ? `${styleLabel(program.style)} — ${program.name}` : "their picked program";

    return e("div", { style: { ...styles.sessionForm, marginTop: 20 } },
      e("div", { style: { display: "flex", justifyContent: "space-between", alignItems: "center" } },
        e("span", { style: styles.profileLabel }, "Program payment"),
        e("span", {
          style: {
            fontSize: 11, fontWeight: 600, letterSpacing: "0.03em",
            color: paid ? C.good : C.ink3, display: "flex", alignItems: "center", gap: 4
          }
        },
          e(Icon, { name: "lock", size: 11, color: paid ? C.good : C.ink3 }),
          paid ? "Active" : "Not paid — can't see this program's exercises yet"
        )
      ),
      e("p", { style: { ...styles.profileGoalText, marginTop: 6 } }, "Picked: ", label),
      paid && error && e("span", { style: { ...styles.inlineError, display: "block", marginTop: 6 } }, error),
      paid
        ? (confirmRevoke
            ? e("div", { style: { ...styles.deleteConfirmBar, flexDirection: "column", alignItems: "stretch", gap: 8, marginTop: 10 } },
                e("span", { style: styles.deleteConfirmText }, "Turn off this client's access? They'll stop seeing this program's exercises until you mark it paid again — it stays picked, it just re-locks."),
                e("div", { style: { display: "flex", gap: 8 } },
                  e("button", { style: { ...styles.confirmCancelBtn, flex: 1 }, onClick: () => setConfirmRevoke(false) }, "Cancel"),
                  e("button", { style: { ...styles.confirmDangerBtn, flex: 1 }, onClick: handleRevoke }, "Turn off")
                )
              )
            : e("button", { style: { ...styles.demoLinkBtn, marginTop: 10, color: C.critical }, onClick: () => setConfirmRevoke(true) }, "Turn off access")
          )
        : (unlocking
            ? e("div", { style: { marginTop: 10 } },
                e("label", { style: { ...styles.formLabel, marginTop: 0 } }, "Amount received"),
                e("input", { style: styles.input, type: "number", placeholder: "Amount", value: amount, onChange: (ev) => setAmount(ev.target.value) }),
                e("input", { style: { ...styles.input, marginTop: 8 }, type: "date", value: date, onChange: (ev) => setDate(ev.target.value) }),
                error && e("span", { style: styles.inlineError }, error),
                e("div", { style: { display: "flex", gap: 8, marginTop: 10 } },
                  e("button", { style: { ...styles.saveBtn, marginTop: 0, flex: 1, ...(saving ? styles.btnDisabled : {}) }, disabled: saving, onClick: handleSubscribe }, saving ? "Saving…" : "Mark as paid & unlock"),
                  e("button", { style: { ...styles.demoLinkBtn, padding: "0 10px" }, onClick: () => { setUnlocking(false); setError(""); setAmount(String(PROGRAM_PRICE)); } }, "Cancel")
                )
              )
            : e("button", { style: { ...styles.demoLinkBtn, marginTop: 10 }, onClick: () => setUnlocking(true) }, `Mark as paid ($${PROGRAM_PRICE}) →`)
         )
    );
  }

  // Sept 12 2026, Jimmy: "for each section his own logo related to programs
  // or levels its more fun" — a small colored icon badge per program, read
  // from its name (Beginner/Intermediate/Advanced) first and falling back to
  // its training style, so a stacked list of cards is visually distinct
  // instead of the same gray dumbbell square repeated down the page.
  function programVisual(name, style) {
    const n = (name || "").toLowerCase();
    if (/\b(beginner|foundation|starter|intro)\b/.test(n)) return { icon: "sparkle", color: C.good };
    if (/\b(intermediate|builder|progression)\b/.test(n)) return { icon: "trendUp", color: C.brand };
    if (/\b(advanced|elite|pro|master)\b/.test(n)) return { icon: "flame", color: C.critical };
    // Sept 15 2026, Jimmy: "do logo for every section here" — pointed at the
    // Programs list where the 5 circuit programs all share the
    // circuit_training style and so all fell through to the same "swap"
    // badge below, right back to the repeated-gray-box look the level check
    // above was built to fix. Name-match the specific circuit programs to
    // their own icon/color too, one level down from Beginner/Intermediate/
    // Advanced — same idea, just keyed off what's actually in the name.
    if (/\btotal body\b/.test(n)) return { icon: "activity", color: C.brand };
    if (/\bupper\s*\/?\s*lower\b/.test(n)) return { icon: "trendUp", color: C.clientAccent };
    if (/\bbodyweight\b/.test(n) || /\bat home\b/.test(n)) return { icon: "user", color: C.good };
    if (/\bcore\b/.test(n) || /\bconditioning\b/.test(n)) return { icon: "flame", color: C.warning };
    if (/\bstrength.endurance\b/.test(n) || /\bendurance\b/.test(n)) return { icon: "trophy", color: C.critical };
    const byStyle = { powerlifting: "dumbbell", calisthenics: "activity", hyrox: "clock", general_resistance: "dumbbell", circuit_training: "swap" };
    return { icon: byStyle[style] || "dumbbell", color: C.brand };
  }

  // A rounded, tinted square carrying one icon — the shared "logo" shape
  // behind both programVisual (above) and dietPlanVisual (near DietPanel).
  function IconBadge({ icon, color, size = 44 }) {
    return e("div", {
      style: {
        width: size, height: size, borderRadius: Math.round(size * 0.3), flexShrink: 0,
        background: withAlpha(color, 0.16), border: `1px solid ${withAlpha(color, 0.32)}`,
        display: "flex", alignItems: "center", justifyContent: "center"
      }
    }, e(Icon, { name: icon, size: Math.round(size * 0.42), color, strokeWidth: 2.1 }));
  }

export { ExerciseLibraryPanel, ExerciseContent, ProgramRequestRow, ProgramRequestsPanel, ExerciseForm, ProgramSetsForm, ProgramPaymentCard, programVisual, IconBadge };
